// soma.mjs — a função que vamos testar
export function soma(a, b) {
  return a + b;
}

// soma.test.mjs — o arquivo de testes
import { test } from 'node:test';        // declara um teste
import assert from 'node:assert/strict'; // o "conferente" das respostas
import { soma } from './soma.mjs';       // a função sob teste

test('soma dois números', () => {
  const resultado = soma(2, 3);   // 1. chama a função
  assert.equal(resultado, 5);     // 2. confere se devolveu 5
});

test('soma números negativos', () => {
  assert.equal(soma(-1, -1), -2);
});

